using System;
using System.ComponentModel.DataAnnotations;
using System.ComponentModel.DataAnnotations.Schema;

namespace Media.DBContext.Models;

/// <summary>
/// Maps a local record to the record of a partner it is synchronized with.
/// </summary>
[Table("federation_record_links")]
public class FederationRecordLink
{
  /// <summary>
  /// Primary key. Autogenerated.
  /// </summary>
  [Key]
  public Guid LinkId { get; set; }

  /// <summary>
  /// The id of the partner.
  /// </summary>
  public Guid PeerId { get; set; }
  public FederationPeer Peer { get; set; } = null!;

  /// <summary>
  /// The id of the local record.
  /// </summary>
  public Guid LocalRecordId { get; set; }
  public Record LocalRecord { get; set; } = null!;

  /// <summary>
  /// The id of the record on the partner instance.
  /// </summary>
  public Guid RemoteRecordId { get; set; }

  /// <summary>
  /// The direction the record was synchronized.
  /// </summary>
  public int Direction { get; set; }

  /// <summary>
  /// The id of the transaction shared by both instances.
  /// </summary>
  public Guid TransactionId { get; set; }

  /// <summary>
  /// Date when the record was synchronized.
  /// </summary>
  public DateTime SyncedAt { get; set; }

  /// <summary>
  /// Date when the metadata of the record were synchronized the last time.
  /// </summary>
  public DateTime UpdatedAt { get; set; }
}
